// ── GLASS BUTTON ──
function GlassBtn({ children, href, onClick, variant = "default", small, style = {} }) {
  const [h, setH] = useState(false);
  const base = {
    display: "inline-flex", alignItems: "center", gap: "0.45rem",
    padding: small ? "0.42rem 1rem" : "0.65rem 1.55rem",
    borderRadius: 50, fontSize: small ? "0.78rem" : "0.88rem",
    fontWeight: 500, fontFamily: "\'DM Sans\', sans-serif",
    cursor: "pointer", textDecoration: "none",
    border: "1.5px solid rgba(255,255,255,0.2)",
    background: h ? "rgba(255,255,255,0.16)" : "rgba(255,255,255,0.09)",
    backdropFilter: "blur(18px)", WebkitBackdropFilter: "blur(18px)",
    color: "#fff",
    boxShadow: h
      ? "0 8px 30px rgba(0,0,0,0.35), inset 0 1px 0 rgba(255,255,255,0.22), inset 0 -1px 0 rgba(0,0,0,0.1)"
      : "0 2px 14px rgba(0,0,0,0.22), inset 0 1px 0 rgba(255,255,255,0.16)",
    transform: h ? "translateY(-2px)" : "translateY(0)",
    transition: "all 0.25s ease",
    letterSpacing: "0.01em", position: "relative", overflow: "hidden",
    ...style,
  };
  const accentExtra = variant === "accent" ? {
    background: h ? "rgba(230,57,70,0.32)" : "rgba(230,57,70,0.18)",
    border: "1.5px solid rgba(230,57,70,0.42)",
    color: "#ff8a93",
    boxShadow: h ? "0 8px 28px rgba(230,57,70,0.3)" : "0 2px 14px rgba(230,57,70,0.15)",
  } : {};
  const finalStyle = { ...base, ...accentExtra };
  if (href) return <a href={href} style={finalStyle} target={href.startsWith("http") ? "_blank" : undefined} rel="noreferrer" onMouseEnter={() => setH(true)} onMouseLeave={() => setH(false)}>{children}</a>;
  return <button style={finalStyle} onClick={onClick} onMouseEnter={() => setH(true)} onMouseLeave={() => setH(false)}>{children}</button>;
}

// ── FADE IN ──
function FadeIn({ children, delay = 0, style = {} }) {
  const ref = useRef(null);
  const [vis, setVis] = useState(false);
  useEffect(() => {
    const obs = new IntersectionObserver(([e]) => { if (e.isIntersecting) { setVis(true); obs.disconnect(); } }, { threshold: 0.08 });
    if (ref.current) obs.observe(ref.current);
    return () => obs.disconnect();
  }, []);
  return (
    <div ref={ref} style={{ opacity: vis ? 1 : 0, transform: vis ? "translateY(0)" : "translateY(28px)", transition: `opacity 0.6s ease ${delay}s, transform 0.6s ease ${delay}s`, ...style }}>
      {children}
    </div>
  );
}

// ── GLASS CARD ──
function Card({ children, t, style = {} }) {
  const [h, setH] = useState(false);
  return (
    <div onMouseEnter={() => setH(true)} onMouseLeave={() => setH(false)} style={{
      background: h ? t.glass : t.card,
      backdropFilter: "blur(16px)", WebkitBackdropFilter: "blur(16px)",
      border: `1px solid ${h ? t.glassBorder : t.border}`,
      borderRadius: 20, transition: "all 0.35s ease",
      transform: h ? "translateY(-6px)" : "translateY(0)",
      boxShadow: h ? "0 20px 60px rgba(0,0,0,0.4)" : "0 4px 20px rgba(0,0,0,0.15)",
      position: "relative", overflow: "hidden", ...style,
    }}>
      <div style={{ position: "absolute", top: 0, left: 0, right: 0, height: 2, background: `linear-gradient(90deg,${t.accent},${t.accent2})`, opacity: h ? 1 : 0, transition: "opacity 0.35s" }} />
      {children}
    </div>
  );
}

