function CItem({ t, icon, label, val, href }) {
  const [h, setH] = useState(false);
  const El = href ? "a" : "div";
  return (
    <El href={href} target={href?.startsWith("http") ? "_blank" : undefined} rel="noreferrer" onMouseEnter={() => setH(true)} onMouseLeave={() => setH(false)} style={{ display: "flex", alignItems: "center", gap: "1rem", padding: "0.9rem 1.1rem", borderRadius: 14, background: h ? t.glass : t.card, backdropFilter: "blur(12px)", WebkitBackdropFilter: "blur(12px)", border: `1px solid ${h ? t.glassBorder : t.border}`, transition: "all 0.3s", cursor: href ? "pointer" : "default", textDecoration: "none", color: t.text, boxShadow: h ? "0 4px 20px rgba(0,0,0,0.2), inset 0 1px 0 rgba(255,255,255,0.08)" : "none" }}>
      <span style={{ fontSize: "1rem" }}>{icon}</span>
      <div>
        <div style={{ fontSize: "0.66rem", color: t.muted, marginBottom: 2 }}>{label}</div>
        <div style={{ fontSize: "0.86rem", fontWeight: 500 }}>{val}</div>
      </div>
    </El>
  );
}

// ── FOOTER ──
function Footer({ t }) {
  return (
    <footer style={{ borderTop: `1px solid ${t.border}`, padding: "1.6rem 5%", display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: "1rem", background: t.bg }}>
      <p style={{ fontSize: "0.78rem", color: t.muted }}>© 2026 Nizamudin Khan. All Rights Reserved.</p>
      <div style={{ display: "flex", gap: "1.2rem" }}>
        {["Facebook", "Instagram", "LinkedIn"].map(s => (
          <a key={s} href="#" style={{ fontSize: "0.78rem", color: t.muted, textDecoration: "none", transition: "color 0.2s" }}
            onMouseEnter={e => e.target.style.color = t.text} onMouseLeave={e => e.target.style.color = t.muted}>{s}</a>
        ))}
      </div>
    </footer>
  );
}

// ── FONT INJECTOR ──
function Fonts() {
  useEffect(() => {
    const l = document.createElement("link");
    l.href = "https://fonts.googleapis.com/css2?family=Syne:wght@400;600;700;800&family=DM+Sans:wght@300;400;500&display=swap";
    l.rel = "stylesheet";
    document.head.appendChild(l);
    const s = document.createElement("style");
    s.textContent = `
      * { margin:0; padding:0; box-sizing:border-box; }
      html { scroll-behavior:smooth; }
      ::-webkit-scrollbar { width:4px; }
      ::-webkit-scrollbar-track { background:#060a12; }
      ::-webkit-scrollbar-thumb { background:#e63946; border-radius:2px; }
      @media(max-width:640px) {
        .nav-links-desktop { display:none !important; }
      }
    `;
    document.head.appendChild(s);
  }, []);
  return null;
}

// ── APP ──
export default function App() {
  const [isDark, setIsDark] = useState(true);
  const [active, setActive] = useState("Home");
  const t = isDark ? dark : light;

  useEffect(() => {
    document.body.style.background = t.bg;
    document.body.style.color = t.text;
    document.body.style.fontFamily = "\'DM Sans\', sans-serif";
    document.body.style.overflowX = "hidden";
  }, [isDark, t]);

  return (
    <div style={{ background: t.bg, color: t.text, fontFamily: "\'DM Sans\', sans-serif", minHeight: "100vh" }}>
      <Fonts />
      <Nav t={t} isDark={isDark} toggleTheme={() => setIsDark(!isDark)} active={active} setActive={setActive} />
      <Hero t={t} isDark={isDark} />
      <Skills t={t} />
      <Projects t={t} />
      <Tools t={t} />
      <Experience t={t} />
      <Contact t={t} />
      <Footer t={t} />
    </div>
  );
}
